import{z as s,x as B,o as E,c,q as t,j as r,D as e,d as A,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"JSON schema 编译优化","description":"","frontmatter":{"title":"JSON schema 编译优化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-schema-compile.md","filePath":"llm/dec-schema-compile.md","lastUpdated":1791063341000}'),d={name:"llm/dec-schema-compile.md"};function i(m,a,p,h,C,u){const o=B("Mermaid");return E(),c("div",null,[a[2]||(a[2]=t('<h1 id="json-schema-编译优化" tabindex="-1">JSON schema 编译优化 <a class="header-anchor" href="#json-schema-编译优化" aria-label="Permalink to &quot;JSON schema 编译优化&quot;">​</a></h1><div class="epigraph"><p>编译的艺在切一刀：栈无关的 token 类离线算成查表，栈相关的留给运行时；全表预计算是把内存烧给用不到的状态。</p><footer>—— 据 Willard &amp; Louf, arXiv:2307.09702 与 Dong et al., XGrammar, arXiv:2411.15100 的编译口径整理</footer></div><p><a href="/llm/dec-controlled-advanced">上一课</a>把受控生成拉成四层地图，把结构这一层标给了本课程。基础侧的语义已经齐了：<a href="/llm/json-schema-decode">JSON Schema 课</a>写 schema 作为产品合同，<a href="/llm/json-constrained-decode">JSON 约束课</a>写类型进掩码，<a href="/llm/structured-output-overhead">结构化输出的开销</a>点了「编译要缓存」的名。本课只钻编译本身：从一份 schema 文本到逐步可查的掩码，时间与内存花在哪、怎么压。后课的缓存与复用默认建立在本课的编译产物上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译器的输入是 schema，输出不是「一个自动机」就完事：掩码必须定义在 <strong>token 字母表</strong>上，而 schema 的字符文法与 BPE 不对齐——数字、转义、键名都可能被切成多种子词路径。基准做法是对每个自动机状态扫描整个词表，成本 \\(O(|Q|\\cdot|\\mathcal{V}|)\\)：嵌套对象与递归 <code>$ref</code> 把 \\(|Q|\\) 推高，十万级词表把乘积推到不可行。若每个请求现场编译，冷启动全部打在 TTFT；若全表预计算，内存先炸。缺口是三个决策：schema 怎么简化、字符级怎么升到 token 级、预计算与运行时在哪切一刀。</p><p><span class="marginnote">直觉类比：schema 是字符级的规则（「这里要一个引号、那里一个冒号」），而模型一次吐的是一个完整 token（可能是 <code>&quot;:</code> 也可能是 <code>&quot;name</code>）。编译器干的活，就是把字符规则翻译成 token 规则——像把「每小时限速 60 公里」换算成「每分钟限速 1 公里」。换算错了（文法合法的字符序列拼不出任何 token），约束就会卡死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先简化 schema，再编译。</strong> 关掉 <code>additionalProperties</code>、固定键序（声明序或字典序）把对象语言压向近正则；<code>pattern</code> 下的子正则单独编译，防状态爆炸；超大 schema 拆成顶层信封加小对象，而不是一次编进掩码。这些是产品决策：紧 schema 好解析、好加速，松 schema 好写。</p><p><strong>字符级到 token 级。</strong> 对每个状态扫描词表，把「token 的字节串能否从该状态合法消费」的判定结果建成索引：Outlines 在编译期建好状态到 token 集合的映射，热路径查表；XGrammar 把与栈无关的 token 类离线预计算成掩码表，依赖栈的 token 在运行时按当前格局补算，并用自适应缓存记住见过的格局。</p><p><strong>存储用位图或稀疏索引。</strong> 合法集通常远小于词表；逐步传掩码时稀疏结构省带宽，与 GPU 前向重叠的细节归<a href="/llm/structured-output-overhead">开销课</a>。</p><p><strong>编译要设预算。</strong> 深层嵌套或狂野 pattern 让编译超时、内存超限时，应降级为「校验—重试」路径并打点，而不是让请求挂在编译器里。禁用来自用户的任意 pattern，或限时限内存——正则编译炸弹是老问题。</p>',11)),(E(),r(l,null,{default:e(()=>[n(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCH%5B%22JSON%20Schema%22%5D%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%E4%B8%8E%E7%AE%80%E5%8C%96%EF%BC%9A%E9%94%AE%E5%BA%8F%20%2F%20%E6%94%B6%E7%B4%A7%20%2F%20%E6%8B%86%E5%88%86%22%5D%0A%20%20NORM%20--%3E%20C%5B%22%E7%BC%96%E8%AF%91%E5%AD%97%E7%AC%A6%E7%BA%A7%20FSM%20%E6%88%96%20PDA%22%5D%0A%20%20C%20--%3E%20PRE%5B%22%E6%A0%88%E6%97%A0%E5%85%B3%20token%20%E7%B1%BB%EF%BC%9A%E7%A6%BB%E7%BA%BF%E6%8E%A9%E7%A0%81%E8%A1%A8%22%5D%0A%20%20C%20--%3E%20RT%5B%22%E6%A0%88%E7%9B%B8%E5%85%B3%20token%EF%BC%9A%E8%BF%90%E8%A1%8C%E6%97%B6%E8%A1%A5%E7%AE%97%22%5D%0A%20%20RT%20--%3E%20CACHE%5B%22%E6%A0%BC%E5%B1%80%E6%8E%A9%E7%A0%81%E7%BC%93%E5%AD%98%22%5D%0A%20%20PRE%20--%3E%20M%5B%22%E9%80%90%E6%AD%A5%E6%8E%A9%E7%A0%81%22%5D%0A%20%20CACHE%20--%3E%20M%0A%20%20M%20--%3E%20SAMP%5B%22%E9%87%87%E6%A0%B7%E6%A0%B8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优化的每一步都在改复杂度常数或指数。固定键序与禁止额外键，等价于把「对象」的语言从需要记忆任意键集合压成有限枚举，\\(|Q|\\) 从组合级降到线性级。离线预计算把「每步扫词表」换成「每步查表」，代价是一次性 \\(O(|Q|\\cdot|\\mathcal{V}|)\\)；XGrammar 的切法把这一项限定在栈无关类上，栈相关部分摊到首次出现，是内存与运行时的折中。自适应缓存有效的原因是真实流量的格局分布高度集中：键名、固定标点、常见类型反复出现，缓存命中率天然高。</p><p>编译必须绑定分词器：换模型或换 tokenizer，token 级掩码表整体作废，这不是缓存失效，是正确性失效。可表示性空洞（文法允许、词表路径不允许）在编译期就应测出来，测法见 <a href="/llm/json-constrained-decode">JSON 约束课</a>。</p><p><span class="marginnote">常见误区：初学者容易以为「编译慢一点等它算完就行」。实际上恶意或失控的 schema（深度递归 <code>$ref</code>、巨型正则）不是慢，是不终止——CPU 和内存会被一直吃下去。所以编译器必须带预算（超时、内存上限），超了就走「不约束、事后校验重试」的降级路径，让请求失败得快而便宜。</span></p><p><span class="marginnote">量级感受：\\(|Q|=10^4\\)、\\(|\\mathcal{V}|=10^5\\) 时全表是 \\(10^9\\) 级条目，位图也要数百 MB——「全部离线」从来不是选项，切分才是。</span></p><p>「栈无关」与「栈相关」的区别决定了离线与在线的切分线。栈无关的 token 只看当前状态就能判定；栈相关的要看括号配对史，状态相同、栈不同，合法性就不同：</p>',6)),(E(),r(l,null,{default:e(()=>[n(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%8A%B6%E6%80%81%EF%BC%9A%E5%9C%A8%E5%AF%B9%E8%B1%A1%E5%80%BC%E4%BD%8D%E7%BD%AE%22%5D%20--%3E%20Q%7B%22%E8%AF%A5%20token%20%E6%98%AF%E5%90%A6%EF%BC%9Cbr%2F%EF%BC%9E%E4%BE%9D%E8%B5%96%E6%8B%AC%E5%8F%B7%2F%E5%BC%95%E5%8F%B7%E9%85%8D%E5%AF%B9%E6%A0%88%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E5%A6%82%20'null'%E3%80%81'%3A%20'%E3%80%81%E6%95%B0%E5%AD%97%E5%89%8D%E7%BC%80%22%7C%20OFF%5B%22%E7%A6%BB%E7%BA%BF%E9%A2%84%E8%AE%A1%E7%AE%97%E8%BF%9B%E6%8E%A9%E7%A0%81%E8%A1%A8%3Cbr%2F%3E%E6%89%80%E6%9C%89%E8%AF%B7%E6%B1%82%E5%85%B1%E4%BA%AB%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E5%A6%82%E5%AF%B9%E8%B1%A1%E5%BC%80%E6%8B%AC%E5%8F%B7%E3%80%81%E6%95%B0%E7%BB%84%E5%BC%80%E6%8B%AC%E5%8F%B7%E3%80%81%E5%B8%A6%E5%BC%95%E5%8F%B7%E4%B8%B2%E7%9A%84%E5%A4%B4%22%7C%20ON%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E6%8C%89%E5%BD%93%E5%89%8D%E6%A0%88%E8%A1%A5%E7%AE%97%3Cbr%2F%3E%E9%A6%96%E6%AC%A1%E8%A7%81%E5%88%B0%E7%9A%84%E6%A0%BC%E5%B1%80%E5%9B%9E%E5%A1%AB%E7%BC%93%E5%AD%98%22%5D%0A%20%20OFF%20--%3E%20T%5B%22%E6%9C%AC%E6%AD%A5%E5%90%88%E6%B3%95%E9%9B%86%22%5D%0A%20%20ON%20--%3E%20T%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">数字实例：一个典型工具调用 schema 编出的状态数 \\(|Q|\\) 约几千到几万。若其中八成 token 判定与栈无关，离线表就只需存这八成；剩下两成在真实流量里九成以上会命中格局缓存——两边叠加，逐步开销从「每次扫十万词表」降到「基本查表」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>编译优化不改变两条老边界：结构合法不等于内容正确；掩码过紧会把模型逼到低概率区，出现重复标点或最短骨架。不要在运行时用 Python 正则逐步过滤词表——那是被 Outlines 论文点名的反面路径。也不要把「编译快」当成 schema 可以随便写的理由：每一层递归与每一条 <code>pattern</code> 都会进编译账单，schema 审查比编译器调参便宜。编译产物的跨请求复用、键设计与失效，是下一课的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编译的三个决策：schema 简化、字符级到 token 级的升级、预计算与运行时的切分。</li><li>固定键序、收紧 <code>additionalProperties</code> 把状态数从组合级压到线性级。</li><li>栈无关 token 类离线成表，栈相关运行时补算加自适应缓存，是内存与延迟的折中。</li><li>编译设预算，超限降级为校验—重试；用户提供的 pattern 要限时限内存。</li><li>编译产物绑定分词器，换模型即重编译，属正确性而非缓存问题。</li><li>出处：Willard &amp; Louf, arXiv:2307.09702；Dong et al., XGrammar, arXiv:2411.15100；Zheng et al., SGLang, NeurIPS 2024。</li></ul>',5))])}const D=s(d,[["render",i]]);export{_ as __pageData,D as default};
